{"code":"const patch = (lines) => ['*** Begin Patch', ...lines, '*** End Patch'].join('\n')
await tools.read({ file_path: 'notes.txt' })
await tools.read({ file_path: 'gone.txt' })
await tools.read({ file_path: 'move-src.txt' })
const success = await tools.apply_patch({ input: patch([
  '*** Add File: created.txt', '+created',
  '*** Update File: notes.txt', '@@', '-hello', '+hi',
  '*** Delete File: gone.txt',
  '*** Update File: move-src.txt', '*** Move to: move-dst.txt', '@@', '-move me', '+moved',
]) })
const caught = async (input) => {
  try { return JSON.stringify(await tools.apply_patch({ input })) }
  catch (error) { return error instanceof Error ? error.message : String(error) }
}
const unread = await caught(patch(['*** Delete File: secret.txt']))
const link = await caught(patch(['*** Delete File: link.txt']))
const partial = await tools.apply_patch({ input: patch([
  '*** Add File: kept.txt', '+kept',
  '*** Add File: ../escape.txt', '+nope',
]) })
return { success: String(success), unread, link, partial: String(partial) }","description":"Apply the guarded patch cases"}

